require_once __DIR__.'/../includes/auth_check.php';requireAdmin();require_once __DIR__.'/../config/database.php';$db=(new Database())->getConnection();if(!$db)die('Database unavailable');
$base=$db->query('SELECT * FROM behavior_baselines ORDER BY id')->fetchAll();$run=$db->query('SELECT * FROM behavior_experiments ORDER BY id DESC LIMIT 1')->fetch();$userCount=(int)$db->query("SELECT COUNT(*) FROM users WHERE email LIKE '%@simulation.kitchenmart.test'")->fetchColumn();$caseCounts=['normal'=>0,'suspicious'=>0];foreach($db->query("SELECT actual_label,COUNT(DISTINCT experiment_case_id,user_id) cases FROM user_activity_logs WHERE source='simulation' GROUP BY actual_label")->fetchAll()as$row)$caseCounts[$row['actual_label']]=(int)$row['cases'];if($run){if($userCount===0)$userCount=(int)$run['user_count'];if(array_sum($caseCounts)===0)$caseCounts=['normal'=>(int)$run['true_negative']+(int)$run['false_positive'],'suspicious'=>(int)$run['true_positive']+(int)$run['false_negative']];}$alertCount=$run?(int)$run['true_positive']+(int)$run['false_positive']:0;
if(($_GET['export']??'')==='csv'){header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename=behavior-analysis.csv');$o=fopen('php://output','w');fwrite($o,"\xEF\xBB\xBF");fputcsv($o,['Metric (English)','Value','Thai description']);if($run)foreach([['Accuracy',$run['accuracy'],'ความถูกต้องรวม'],['Precision',$run['precision_score'],'ความแม่นยำของการแจ้งเตือน'],['Detection Rate / Recall',$run['recall_score'],'อัตราตรวจจับ'],['F1-score',$run['f1_score'],'สมดุล Precision/Recall'],['False Positive Rate',$run['false_positive_rate'],'อัตราแจ้งผู้ใช้ปกติผิด'],['Detection Time (ms)',$run['avg_detection_time_ms'],'เวลาตรวจจับเฉลี่ย']]as$r)fputcsv($o,$r);fputcsv($o,[]);fputcsv($o,['Confusion Matrix','Actual Normal','Actual Suspicious','Row Total']);if($run){fputcsv($o,['Predicted Normal',$run['true_negative'].' TN',$run['false_negative'].' FN',(int)$run['true_negative']+(int)$run['false_negative']]);fputcsv($o,['Predicted Suspicious',$run['false_positive'].' FP',$run['true_positive'].' TP',(int)$run['false_positive']+(int)$run['true_positive']]);fputcsv($o,['Column Total',(int)$run['true_negative']+(int)$run['false_positive'],(int)$run['false_negative']+(int)$run['true_positive'],$run['total_cases']]);}fputcsv($o,[]);fputcsv($o,['Code','Value','Meaning']);if($run)foreach([['TP',$run['true_positive'],'ตรวจพบพฤติกรรมน่าสงสัยถูกต้อง'],['TN',$run['true_negative'],'ระบุพฤติกรรมปกติถูกต้อง'],['FP',$run['false_positive'],'ผู้ใช้ปกติถูกแจ้งว่าน่าสงสัย'],['FN',$run['false_negative'],'พฤติกรรมน่าสงสัยที่ตรวจไม่พบ']]as$r)fputcsv($o,$r);fputcsv($o,[]);fputcsv($o,['Feature','Mean','SD','Threshold','Window (sec)','Samples']);foreach($base as$b)fputcsv($o,[$b['feature_name_en'],$b['mean_value'],$b['sd_value'],'>'.$b['threshold_value'],$b['window_seconds'],$b['sample_count']]);fclose($o);exit;}
$page_title='Behavior Analytics Dashboard';include __DIR__.'/../includes/admin_header.php';?>
