<section class="behavior-overview"><article><i class="fa-solid fa-users"></i><div><small>จำนวน Users</small><strong><?php echo number_format($userCount);?></strong><span>ผู้ใช้จำลอง</span></div></article><article class="normal"><i class="fa-solid fa-user-check"></i><div><small>Normal Cases</small><strong><?php echo number_format($caseCounts['normal']);?></strong><span><?php echo number_format($caseCounts['normal']/$run['total_cases']*100,1);?>% ของทั้งหมด</span></div></article><article class="suspicious"><i class="fa-solid fa-user-secret"></i><div><small>Suspicious Cases</small><strong><?php echo number_format($caseCounts['suspicious']);?></strong><span><?php echo number_format($caseCounts['suspicious']/$run['total_cases']*100,1);?>% ของทั้งหมด</span></div></article><article class="alerts"><i class="fa-solid fa-bell"></i><div><small>Alerts</small><strong><?php echo number_format($alertCount);?></strong><span>TP + FP</span></div></article></section>
<section class="behavior-metrics"><?php foreach([['Accuracy','accuracy','fa-bullseye'],['Precision','precision_score','fa-crosshairs'],['Recall','recall_score','fa-magnifying-glass-chart'],['F1-score','f1_score','fa-scale-balanced'],['False Positive Rate','false_positive_rate','fa-triangle-exclamation']]as[$name,$key,$icon]):$percent=(float)$run[$key]*100;?><article><header><span><?php echo e($name);?></span><i class="fa-solid <?php echo $icon;?>"></i></header><strong><?php echo number_format($percent,2);?>%</strong><div class="metric-track"><i style="width:<?php echo min(100,$percent);?>%"></i></div></article><?php endforeach;?></section>
<div class="behavior-dashboard-grid"><section class="behavior-panel behavior-chart-panel"><header><div><h2>กราฟพฤติกรรม</h2><p>ค่าเฉลี่ยของ Normal User เปรียบเทียบกับ Threshold</p></div><span class="run-code"><?php echo e($run['run_code']);?></span></header><div class="behavior-chart-legend"><span><i class="mean"></i> Mean</span><span><i class="threshold"></i> Threshold</span></div><div class="behavior-bars"><?php foreach($base as$b):$max=max(.001,(float)$b['mean_value'],(float)$b['threshold_value']);?><article><div class="bar-label"><strong><?php echo e($b['feature_name_en']);?></strong><span><?php echo e($b['feature_name_th']);?></span></div><div class="bar-values"><div><i class="mean" style="width:<?php echo (float)$b['mean_value']/$max*100;?>%"></i><b><?php echo number_format($b['mean_value'],2);?></b></div><div><i class="threshold" style="width:<?php echo (float)$b['threshold_value']/$max*100;?>%"></i><b>&gt; <?php echo number_format($b['threshold_value'],2);?></b></div></div></article><?php endforeach;?></div></section><section class="behavior-panel distribution-panel"><header><div><h2>สัดส่วนข้อมูล</h2><p>Normal และ Suspicious Cases</p></div></header><div class="case-donut" style="--suspicious:<?php echo $caseCounts['suspicious']/$run['total_cases']*100;?>%"><div><strong><?php echo number_format($run['total_cases']);?></strong><span>Cases</span></div></div><div class="distribution-legend"><p><i class="normal"></i><span>Normal</span><strong><?php echo number_format($caseCounts['normal']);?></strong></p><p><i class="suspicious"></i><span>Suspicious</span><strong><?php echo number_format($caseCounts['suspicious']);?></strong></p></div></section></div>
<section class="behavior-panel confusion-panel"><header><div><h2>Confusion Matrix</h2><p>ผลทำนายของระบบเปรียบเทียบกับข้อมูลจริง</p></div><span><?php echo number_format($run['total_cases']);?> cases</span></header><div class="confusion-wrap"><table><thead><tr><th></th><th>Actual Normal</th><th>Actual Suspicious</th></tr></thead><tbody><tr><th>Predicted Normal</th><td class="tn"><strong><?php echo number_format($run['true_negative']);?></strong><span>TN · True Negative</span></td><td class="fn"><strong><?php echo number_format($run['false_negative']);?></strong><span>FN · False Negative</span></td></tr><tr><th>Predicted Suspicious</th><td class="fp"><strong><?php echo number_format($run['false_positive']);?></strong><span>FP · False Positive</span></td><td class="tp"><strong><?php echo number_format($run['true_positive']);?></strong><span>TP · True Positive</span></td></tr></tbody></table></div></section>
<section class="behavior-panel baseline-panel"><header><div><h2>Baseline & Threshold</h2><p>Mean และ Sample SD จากข้อมูล Normal พร้อมเกณฑ์ที่นำไปใช้จริง</p></div></header><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Behavior</th><th>Mean</th><th>SD</th><th>Threshold</th><th>Window</th><th>Samples</th></tr></thead><tbody><?php foreach($base as$b):?><tr><td><strong><?php echo e($b['feature_name_en']);?></strong><small><?php echo e($b['feature_name_th']);?></small></td><td><?php echo number_format($b['mean_value'],3);?></td><td><?php echo number_format($b['sd_value'],3);?></td><td><strong>&gt; <?php echo number_format($b['threshold_value'],2);?></strong></td><td><?php echo number_format($b['window_seconds']);?> sec</td><td><?php echo number_format($b['sample_count']);?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="behavior-performance"><article><small>Response Time AVG / P95</small><strong><?php echo number_format($run['avg_response_time_ms'],2);?> / <?php echo number_format($run['p95_response_time_ms'],2);?> ms</strong></article><article><small>Detection Time AVG / P95</small><strong><?php echo number_format($run['avg_detection_time_ms'],2);?> / <?php echo number_format($run['p95_detection_time_ms'],2);?> ms</strong></article><article><small>Throughput</small><strong><?php echo number_format($run['throughput_cases_sec'],2);?> cases/sec</strong></article><article><small>CPU / Peak Memory</small><strong><?php echo number_format($run['cpu_usage_percent'],2);?>% / <?php echo number_format($run['peak_memory_mb'],2);?> MB</strong></article></section>
